arguments.prompt:
You are implementing a Blazor Web App for a logistics company that tracks shipments. The project is already scaffolded at `/tmp/sv-2a803caa29de403eb578fe8a88a134c9/ShipmentTracker/` using `dotnet new blazor -int Auto -ai -au Individual`.

The project structure:
- `ShipmentTracker/` - server project
- `ShipmentTracker.Client/` - client (WebAssembly) project

Key facts about Auto Global mode:
- Interactive components MUST go in the `.Client` project
- Components cannot access DbContext directly - must use HTTP APIs
- Both Program.cs files must register matching service interfaces
- The server project has Identity auth configured with SQLite

## Requirements
1. Dispatchers view a list of shipments with status and destination
2. Customers check their shipment status and estimated delivery
3. Authentication with Individual accounts (already scaffolded)
4. Staff (dispatchers) and customers have different roles

## Implementation Tasks

### 1. Add Shipment entity to the server Data layer

Edit `/tmp/sv-2a803caa29de403eb578fe8a88a134c9/ShipmentTracker/ShipmentTracker/Data/ApplicationDbContext.cs` to add a Shipments DbSet.

Create `/tmp/sv-2a803caa29de403eb578fe8a88a134c9/ShipmentTracker/ShipmentTracker/Data/Shipment.cs`:
```csharp
namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedAt { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string? CustomerId { get; set; }  // ApplicationUser.Id
    public string RecipientName { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Exception
}
```

### 2. Create shared DTOs in the Client project

Create `/tmp/sv-2a803caa29de403eb578fe8a88a134c9/ShipmentTracker/ShipmentTracker.Client/Models/ShipmentDto.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public DateTime CreatedAt { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
}

public class UpdateShipmentStatusDto
{
    public string Status { get; set; } = string.Empty;
}

public class TrackingResultDto
{
    public string TrackingNumber { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public DateTime? EstimatedDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
}
```

### 3. Create service interface in the Client project

Create `/tmp/sv-2a803caa29de403eb578fe8a88a134c9/ShipmentTracker/ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<ShipmentDto>> GetAllShipmentsAsync();
    Task<ShipmentDto?> GetShipmentAsync(int id);
    Task UpdateStatusAsync(int id, string status);
    Task<TrackingResultDto?> TrackShipmentAsync(string trackingNumber);
    Task<List<ShipmentDto>> GetMyShipmentsAsync();
}
```

### 4. Create HttpClient-based implementation in the Client project

Create `/tmp/sv-2a803caa29de403eb578fe8a88a134c9/ShipmentTracker/ShipmentTracker.Client/Services/HttpShipmentService.cs`:
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? [];
    }

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
    {
        return await http.GetFromJsonAsync<ShipmentDto>($"api/shipments/{id}");
    }

    public async Task UpdateStatusAsync(int id, string status)
    {
        await http.PutAsJsonAsync($"api/shipments/{id}/status", new UpdateShipmentStatusDto { Status = status });
    }

    public async Task<TrackingResultDto?> TrackShipmentAsync(string trackingNumber)
    {
        var response = await http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<TrackingResultDto>();
    }

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments/my") ?? [];
    }
}
```

### 5. Create server-side service implementation

Create `/tmp/sv-2a803caa29de403eb578fe8a88a134c9/ShipmentTracker/ShipmentTracker/Services/ServerShipmentService.cs`:
```csharp
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db, AuthenticationStateProvider authStateProvider) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
    {
        var shipment = await db.Shipments.FindAsync(id);
        return shipment is null ? null : MapToDto(shipment);
    }

    public async Task UpdateStatusAsync(int id, string status)
    {
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is not null && Enum.TryParse<ShipmentStatus>(status, out var parsedStatus))
        {
            shipment.Status = parsedStatus;
            await db.SaveChangesAsync();
        }
    }

    public async Task<TrackingResultDto?> TrackShipmentAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        if (shipment is null) return null;
        return new TrackingResultDto
        {
            TrackingNumber = shipment.TrackingNumber,
            Status = shipment.Status.ToString(),
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            EstimatedDelivery = shipment.EstimatedDelivery,
            RecipientName = shipment.RecipientName
        };
    }

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
    {
        var authState = await authStateProvider.GetAuthenticationStateAsync();
        var userId = authState.User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;
        if (userId is null) return [];

        return await db.Shipments
            .Where(s => s.CustomerId == userId)
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        RecipientName = s.RecipientName
    };
}
```

### 6. Create API endpoints on the server

Create `/tmp/sv-2a803caa29de403eb578fe8a88a134c9/ShipmentTracker/ShipmentTracker/Endpoints/ShipmentEndpoints.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;
using System.Security.Claims;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments");

        group.MapGet("/", async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status.ToString(),
                    CreatedAt = s.CreatedAt,
                    EstimatedDelivery = s.EstimatedDelivery,
                    RecipientName = s.RecipientName
                })
                .ToListAsync();
            return Results.Ok(shipments);
        }).RequireAuthorization("Dispatcher");

        group.MapGet("/{id:int}", async (int id, ApplicationDbContext db) =>
        {
            var s = await db.Shipments.FindAsync(id);
            if (s is null) return Results.NotFound();
            return Results.Ok(new ShipmentDto
            {
                Id = s.Id,
                TrackingNumber = s.TrackingNumber,
                Origin = s.Origin,
                Destination = s.Destination,
                Status = s.Status.ToString(),
                CreatedAt = s.CreatedAt,
                EstimatedDelivery = s.EstimatedDelivery,
                RecipientName = s.RecipientName
            });
        }).RequireAuthorization("Dispatcher");

        group.MapPut("/{id:int}/status", async (int id, UpdateShipmentStatusDto dto, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();
            if (!Enum.TryParse<ShipmentStatus>(dto.Status, out var status)) return Results.BadRequest("Invalid status");
            shipment.Status = status;
            await db.SaveChangesAsync();
            return Results.NoContent();
        }).RequireAuthorization("Dispatcher");

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var s = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            if (s is null) return Results.NotFound();
            return Results.Ok(new TrackingResultDto
            {
                TrackingNumber = s.TrackingNumber,
                Status = s.Status.ToString(),
                Origin = s.Origin,
                Destination = s.Destination,
                EstimatedDelivery = s.EstimatedDelivery,
                RecipientName = s.RecipientName
            });
        }).RequireAuthorization();

        group.MapGet("/my", async (ClaimsPrincipal user, ApplicationDbContext db) =>
        {
            var userId = user.FindFirst(ClaimTypes.NameIdentifier)?.Value;
            if (userId is null) return Results.Unauthorized();

            var shipments = await db.Shipments
                .Where(s => s.CustomerId == userId)
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status.ToString(),
                    CreatedAt = s.CreatedAt,
                    EstimatedDelivery = s.EstimatedDelivery,
                    RecipientName = s.RecipientName
                })
                .ToListAsync();
            return Results.Ok(shipments);
        }).RequireAuthorization();
    }
}
```

