@page "/dispatch"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatch Dashboard</PageTitle>

<h1>Shipment Dashboard</h1>

@if (shipments is null)
{
    <p>Loading shipments...</p>
}
else if (!shipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Recipient</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.RecipientName</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge bg-@GetStatusColor(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                    <td>
                        <select class="form-select form-select-sm" value="@shipment.Status"
                                @onchange="e => UpdateStatus(shipment, e.Value?.ToString())">
                            <option value="Pending">Pending</option>
                            <option value="PickedUp">Picked Up</option>
                            <option value="InTransit">In Transit</option>
                            <option value="OutForDelivery">Out for Delivery</option>
                            <option value="Delivered">Delivered</option>
                            <option value="Exception">Exception</option>
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s => string.IsNullOrEmpty(filterText)
            || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(ShipmentDto shipment, string? newStatus)
    {
        if (newStatus is null || newStatus == shipment.Status) return;
        await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
        shipment.Status = newStatus;
    }

    private static string GetStatusColor(string status) => status switch
    {
        "Pending" => "secondary",
        "PickedUp" => "info",
        "InTransit" => "primary",
        "OutForDelivery" => "warning",
        "Delivered" => "success",
        "Exception" => "danger",
        _ => "secondary"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number..."
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isSearching">
                @if (isSearching) { <span class="spinner-border spinner-border-sm"></span> }
                Search
            </button>
        </div>
    </div>
</div>

@if (searchPerformed && trackingResult is null)
{
    <div class="alert alert-warning">No shipment found with that tracking number.</div>
}

@if (trackingResult is not null)
{
    <div class="card">
        <div class="card-header">
            <strong>Tracking #: @trackingResult.TrackingNumber</strong>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>Recipient:</strong> @trackingResult.RecipientName</p>
                    <p><strong>From:</strong> @trackingResult.Origin</p>
                    <p><strong>To:</strong> @trackingResult.Destination</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Status:</strong> <span class="badge bg-@GetStatusColor(trackingResult.Status)">@trackingResult.Status</span></p>
                    <p><strong>Estimated Delivery:</strong> @(trackingResult.EstimatedDelivery?.ToString("MMMM dd, yyyy") ?? "TBD")</p>
                </div>
            </div>
        </div>
    </div>
}

<hr class="my-4" />

<h2>My Shipments</h2>

@if (myShipments is null)
{
    <p>Loading your shipments...</p>
}
else if (!myShipments.Any())
{
    <p>You have no shipments on record.</p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in myShipments)
            {
                <tr>
                    <td>@s.TrackingNumber</td>
                    <td>@s.Destination</td>
                    <td><span class="badge bg-@GetStatusColor(s.Status)">@s.Status</span></td>
                    <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private string trackingNumber = string.Empty;
    private TrackingResultDto? trackingResult;
    private List<ShipmentDto>? myShipments;
    private bool isSearching;
    private bool searchPerformed;

    protected override async Task OnInitializedAsync()
    {
        myShipments = await ShipmentService.GetMyShipmentsAsync();
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await SearchShipment();
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isSearching = true;
        searchPerformed = true;
        trackingResult = await ShipmentService.TrackShipmentAsync(trackingNumber.Trim());
        isSearching = false;
    }

    private static string GetStatusColor(string status) => status switch
    {
        "Pending" => "secondary",
        "PickedUp" => "info",
        "InTransit" => "primary",
        "OutForDelivery" => "warning",
        "Delivered" => "success",
        "Exception" => "danger",
        _ => "secondary"
    };
}

