### 5. Create server-side service implementation

Create `/tmp/sv-2a803caa29de403eb578fe8a88a134c9/ShipmentTracker/ShipmentTracker/Services/ServerShipmentService.cs`:
```csharp
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db, AuthenticationStateProvider authStateProvider) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
    {
        var shipment = await db.Shipments.FindAsync(id);
        return shipment is null ? null : MapToDto(shipment);
    }

    public async Task UpdateStatusAsync(int id, string status)
    {
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is not null && Enum.TryParse<ShipmentStatus>(status, out var parsedStatus))
        {
            shipment.Status = parsedStatus;
            await db.SaveChangesAsync();
        }
    }

    public async Task<TrackingResultDto?> TrackShipmentAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        if (shipment is null) return null;
        return new TrackingResultDto
        {
            TrackingNumber = shipment.TrackingNumber,
            Status = shipment.Status.ToString(),
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            EstimatedDelivery = shipment.EstimatedDelivery,
            RecipientName = shipment.RecipientName
        };
    }

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
    {
        var authState = await authStateProvider.GetAuthenticationStateAsync();
        var userId = authState.User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;
        if (userId is null) return [];

        return await db.Shipments
            .Where(s => s.CustomerId == userId)
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        RecipientName = s.RecipientName
    };
}
```

### 6. Create API endpoints on the server

Create `/tmp/sv-2a803caa29de403eb578fe8a88a134c9/ShipmentTracker/ShipmentTracker/Endpoints/ShipmentEndpoints.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;
using System.Security.Claims;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments");

        group.MapGet("/", async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status.ToString(),
                    CreatedAt = s.CreatedAt,
                    EstimatedDelivery = s.EstimatedDelivery,
                    RecipientName = s.RecipientName
                })
                .ToListAsync();
            return Results.Ok(shipments);
        }).RequireAuthorization("Dispatcher");

        group.MapGet("/{id:int}", async (int id, ApplicationDbContext db) =>
        {
            var s = await db.Shipments.FindAsync(id);
            if (s is null) return Results.NotFound();
            return Results.Ok(new ShipmentDto
            {
                Id = s.Id,
                TrackingNumber = s.TrackingNumber,
                Origin = s.Origin,
                Destination = s.Destination,
                Status = s.Status.ToString(),
                CreatedAt = s.CreatedAt,
                EstimatedDelivery = s.EstimatedDelivery,
                RecipientName = s.RecipientName
            });
        }).RequireAuthorization("Dispatcher");

        group.MapPut("/{id:int}/status", async (int id, UpdateShipmentStatusDto dto, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();
            if (!Enum.TryParse<ShipmentStatus>(dto.Status, out var status)) return Results.BadRequest("Invalid status");
            shipment.Status = status;
            await db.SaveChangesAsync();
            return Results.NoContent();
        }).RequireAuthorization("Dispatcher");

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var s = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            if (s is null) return Results.NotFound();
            return Results.Ok(new TrackingResultDto
            {
                TrackingNumber = s.TrackingNumber,
                Status = s.Status.ToString(),
                Origin = s.Origin,
                Destination = s.Destination,
                EstimatedDelivery = s.EstimatedDelivery,
                RecipientName = s.RecipientName
            });
        }).RequireAuthorization();

        group.MapGet("/my", async (ClaimsPrincipal user, ApplicationDbContext db) =>
        {
            var userId = user.FindFirst(ClaimTypes.NameIdentifier)?.Value;
            if (userId is null) return Results.Unauthorized();

            var shipments = await db.Shipments
                .Where(s => s.CustomerId == userId)
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status.ToString(),
                    CreatedAt = s.CreatedAt,
                    EstimatedDelivery = s.EstimatedDelivery,
                    RecipientName = s.RecipientName
                })
                .ToListAsync();
            return Results.Ok(shipments);
        }).RequireAuthorization();
    }
}
```

